    """Restore color-3 masks using the 180-degree symmetric pattern."""
    out = [row[:] for row in grid]
    height = len(grid)
    width = len(grid[0]) if height else 0
    for r in range(height):
        for c in range(width):
            if grid[r][c] == 3:
                rr, cc = height - 1 - r, width - 1 - c
                if grid[rr][cc] != 3:
                    out[r][c] = grid[rr][cc]
                else:
                    # If both symmetric pixels are masked, use the local
                    # unmasked neighborhood to continue the repeated field.
                    neighbors = []
                    for nr, nc in ((r-1,c),(r+1,c),(r,c-1),(r,c+1)):
                        if 0 <= nr < height and 0 <= nc < width and grid[nr][nc] != 3:
                            neighbors.append(grid[nr][nc])
                    if neighbors:
                        out[r][c] = max(set(neighbors), key=neighbors.count)
    return out

